import{d as g,C as o,o as h,c as d,j as n,a,E as e,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"中庸·第17章","description":"《中庸》第 17 章——舜其大孝：德为圣人，尊为天子；大德必得其位禄名寿，天之生物因其材而笃焉。","frontmatter":{"title":"中庸·第17章","description":"《中庸》第 17 章——舜其大孝：德为圣人，尊为天子；大德必得其位禄名寿，天之生物因其材而笃焉。","category":"guide","aliases":["第17章","中庸第17章","舜其大孝"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-17.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-17.md","lastUpdated":1790316338000}'),u={name:"lizhimingde/sishu-wujing/zhongyong/chapter-17.md"},x=g({...u,setup(p){const r=[{id:"daxiao",label:"舜其大孝也与 · 德为圣人，尊为天子",showLabel:!0,sentences:[["子曰：“舜其",{text:"大孝",glossary:"daxiao"},"也",{text:"与",glossary:"yuzai"},"！德为圣人，尊为天子，富有四海之内。",{text:"宗庙飨之",glossary:"zongmiao"},"，",{text:"子孙保之",glossary:"zisun"},"。"]],note:"孔子赞舜为大孝：「德为圣人，尊为天子，富有四海之内。宗庙飨之，子孙保之」——其德是圣人，其位是天子，富有四海，宗庙祭祀他，子孙保守其业。可见「大孝」不止于养亲。"},{id:"dade",label:"大德必得其位禄名寿 · 栽者培之，倾者覆之",showLabel:!0,sentences:[["故大德必得其位，必得其禄，必得其名，必得其寿。故天之生物，必",{text:"因其材而笃焉",glossary:"yincai"},"。故",{text:"栽者培之",glossary:"zaizhe"},"，",{text:"倾者覆之",glossary:"qingzhe"},"，"]],note:"「故大德必得其位，必得其禄，必得其名，必得其寿」——有大德者，位、禄、名、寿四者必得。又以自然作比：「天之生物，必因其材而笃焉」——天生物，必依其材质而厚待之；「栽者培之，倾者覆之」——能栽植的加以培养，倒伏的任其倾覆。"},{id:"shouming",label:"嘉乐君子 · 大德者必受命",showLabel:!0,sentences:[["《诗》曰：‘",{text:"嘉乐君子",glossary:"jiale"},"，",{text:"宪宪令德",glossary:"xianxian"},"！宜民宜人；受禄于天；保佑命之，自天",{text:"申之",glossary:"shenzhi"},"！’故大德者必",{text:"受命",glossary:"shouming"},"。”"]],note:"引《诗》「嘉乐君子，宪宪令德……受禄于天；保佑命之，自天申之」——赞美君子有盛明之德，宜于民人，受禄于天，天保佑他、再三申命。故结论曰「大德者必受命」——有大德者必受天命。"}],s=[{id:"daxiao",term:"大孝",pinyin:"dà xiào",meaning:"孝之大者。朱注：「子孙，谓虞思、陈胡公之属」——舜之后裔受封，故云「子孙保之」。"},{id:"yuzai",term:"与",pinyin:"yú",meaning:"同「欤」，句末语气词。"},{id:"zongmiao",term:"宗庙飨之",pinyin:"zōng miào xiǎng zhī",meaning:"宗庙祭祀他。飨：同「享」，祭祀。"},{id:"zisun",term:"子孙保之",pinyin:"zǐ sūn bǎo zhī",meaning:"子孙保有他的基业。"},{id:"yincai",term:"因其材而笃焉",pinyin:"yīn qí cái ér dǔ yān",meaning:"依其材质而厚待它。材：资质；笃：厚。"},{id:"zaizhe",term:"栽者培之",pinyin:"zāi zhě péi zhī",meaning:"栽种的加以培育。栽：植；培：气至而滋息。"},{id:"qingzhe",term:"倾者覆之",pinyin:"qīng zhě fù zhī",meaning:"倾倒的加以倾覆。朱注：「气反而游散则覆。」"},{id:"jiale",term:"嘉乐君子",pinyin:"jiā lè jūn zǐ",meaning:"《诗·大雅·假乐》句。嘉乐：美善而安乐。"},{id:"xianxian",term:"宪宪令德",pinyin:"xiǎn xiǎn lìng dé",meaning:"显明的美德。宪宪：《诗》作「显显」；令：善。"},{id:"shenzhi",term:"申之",pinyin:"shēn zhī",meaning:"重复、加重。朱注：「申，重也。」"},{id:"shouming",term:"受命",pinyin:"shòu mìng",meaning:"受天命而为天子。朱注：「受命者，受天命为天子也。」"}];return(y,i)=>{const l=o("DaoTextReading"),t=o("DaoKeywordCards");return h(),d("div",null,[i[0]||(i[0]=n("h1",{id:"中庸·第17章",tabindex:"-1"},[a("中庸·第17章 "),n("a",{class:"header-anchor",href:"#中庸·第17章","aria-label":'Permalink to "中庸·第17章"'},"​")],-1)),i[1]||(i[1]=n("h2",{id:"【原典层】原文",tabindex:"-1"},[a("【原典层】原文 "),n("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),i[2]||(i[2]=n("p",null,[a("第十七章以舜为例说「大孝」，并推出一条通则："),n("strong",null,"大德必得其位、禄、名、寿"),a("（朱注谓舜年百有十岁，正应「必得其寿」）；末以《诗》句收在「大德者必受命」。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),e(l,{colophon:"舜其大孝 · 大德必得其位 · 栽者培之",tone:"ink",sections:r,glossary:s,"default-mode":"slips","aria-label":"中庸·第17章 原文"}),i[3]||(i[3]=n("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[a("【原典层】注音与字词 "),n("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),e(t,{items:[{term:"大孝",pinyin:["dà","xiào"],meaning:"孝之大者。舜之后裔受封，故曰「子孙保之」。"},{term:"宗庙飨之",pinyin:["zōng","miào","xiǎng","zhī"],meaning:"宗庙祭祀他。飨：同「享」。"},{term:"因其材而笃焉",pinyin:["yīn","qí","cái","ér","dǔ","yān"],meaning:"依其材质而厚待它。材：资质；笃：厚。"},{term:"栽者培之",pinyin:["zāi","zhě","péi","zhī"],meaning:"栽种的加以培育。"},{term:"倾者覆之",pinyin:["qīng","zhě","fù","zhī"],meaning:"倾倒的加以倾覆——天之道，因材而笃。"}]}),e(t,{items:[{term:"嘉乐君子",pinyin:["jiā","lè","jūn","zǐ"],meaning:"《诗·大雅·假乐》句。嘉乐：美善而安乐。"},{term:"宪宪令德",pinyin:["xiǎn","xiǎn","lìng","dé"],meaning:"显明的美德。宪宪：《诗》作「显显」；令：善。"},{term:"受命",pinyin:["shòu","mìng"],meaning:"受天命而为天子。朱注：「受命者，受天命为天子也。」"},{term:"必得其位禄名寿",pinyin:["bì","dé","qí","wèi","lù","míng","shòu"],meaning:"大德之人必得位、禄、名、寿。此为儒家的德福相称之说，读时宜从「德为根本、福为自然之势」上体会。"}]}),i[4]||(i[4]=m('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>舜其大孝也与 · 德为圣人</strong>：孔子说：「舜真是大孝啊！德为圣人，尊为天子，富有四海之内。宗庙祭祀他，子孙保有他的基业。」</p><p><strong>大德必得其位禄名寿</strong>：所以大德之人必定得到应有的位、禄、名、寿。所以天生育万物，必依其材质而厚待它：栽种的加以培育，倾倒的加以倾覆。</p><p><strong>嘉乐君子 · 大德者必受命</strong>：《诗经》说：「嘉美安乐的君子，有显明的美德！宜于民、宜于人；受禄于天；保佑他、命令他，从天再加重于他！」所以大德之人必受天命。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第十七章由舜说起：<strong>德为圣人、尊为天子、富有四海、宗庙飨之、子孙保之</strong>——然后推出一条通则：「<strong>故大德必得其位，必得其禄，必得其名，必得其寿。</strong>」</p><p>接着是天道的一句比喻：「天之生物，必因其材而笃焉。故栽者培之，倾者覆之。」最后引《诗》，收在「大德者必受命」。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它是全篇第一次把「德」与「福」连起来说</strong>：位、禄、名、寿四者，是「大德」的自然之应（朱注补一句「舜年百有十岁」，正应「寿」）。读时要留意：这是<strong>德为根本</strong>的说法，不是「做了好事必然升官发财」的因果保证——朱子说「天之生物，必因其材而笃焉」，重心落在「材」上。</li><li><strong>「栽者培之，倾者覆之」是一句极简的天道观</strong>：天不偏私，只依其材。所以功夫在自己这边——<strong>自植其材</strong>。</li><li><strong>它与第 6 章连成舜的两面</strong>：第 6 章说舜之「大知」（智），本章说舜之「大孝」（德）。同一个人，两面都被举为典范。</li><li><strong>它给后文的大舜—文王—武王—周公一线起了头</strong>：第 18、19 章接着讲文王、武王、周公，德与礼在此后一路展开。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>把重心放回「材」上</strong>：想得到什么，先看自己是什么材——「栽者培之」。</li><li><strong>德福之间不设直线</strong>：位、禄、名、寿是「必得」之说，宜作<strong>德为根基</strong>解，而不是成功学承诺。</li><li><strong>大孝的分量</strong>：舜之孝不止于顺，更在德业可传（宗庙飨之、子孙保之）。</li><li><strong>一句可自问的话</strong>：我今日所忙，是在培自己的材，还是在求果？</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>孔子说：舜真是大孝啊——德为圣人，位为天子，富有四海；宗庙祭祀他，子孙守着他的基业。</p><p>由此他说出一条通则：<strong>有大德的人，必然得到相应的位、禄、名、寿。</strong> 天生长万物，总是顺着它的材质去厚待它：<strong>该培的培，该覆的覆。</strong></p><p>《诗经》说得更直：美德显明的君子，受禄于天，天还一再加重他。所以<strong>大德者必受天命。</strong></p><p>这里要留一分清醒：本章的重心不在「德能换福」，而在**「天因其材」**——先要有那个材。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「大德必得其位、禄、名、寿」——我愿意把它读成「德为根本」，还是「好人有好报」？两者的差别在哪里？</li><li>「栽者培之，倾者覆之」——我目前是在「培」，还是在「倾」？</li><li>舜之孝的分量不只在顺，还在「可传」——我准备留下什么？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-16">中庸·第16章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-18">中庸·第18章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',24))])}}});export{c as __pageData,x as default};
